var a=`1047-nasi-padang`;var n=`world-1047`;var s=`ID`;var t=`southeast-asia`;var o=4;var r=173;var d={en:`Nasi Padang`,ua:`Насі паданг`};var l={en:`Nasi Padang is a dish from Indonesia prepared with jasmine rice, beef chuck, coconut milk, lemongrass. This is a home-scale version with measured ingredients in the individual steps where they are used. Nasi Padang is a varied meal of rice and multiple side dishes, not one fixed recipe; this is one example plate.`,ua:`Насі паданг, страва кухні країни Індонезія, яку готують із таких продуктів: рис жасмин, яловича лопатка, кокосове молоко, лемонграс. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Насі паданг, трапеза з рису та різних додатків, а не один усталений рецепт; тут приклад набору страв.`};var g=[{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 25 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 25 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:25,i:[[`jasmine-rice`,450,`g`],[`water`,700,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 125 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 125 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:125,i:[[`beef-chuck`,700,`g`],[`coconut-milk`,650,`ml`],[`lemongrass`,2,`pcs`],[`galangal`,25,`g`],[`thai-red-curry-paste`,55,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`green-beans`,250,`g`],[`shallot`,120,`g`],[`canola-oil`,40,`ml`]]},{en:`Build one nasi Padang-style plate with rice and the fully cooked coconut beef and vegetables; regional nasi Padang normally offers several distinct side dishes.`,ua:`Зберіть тарілку у стилі насі паданг із рису, готової яловичини в кокосовому соусі та овочів; у традиції зазвичай пропонують кілька окремих додатків.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,4,`pcs`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`cucumber`,180,`g`]]}];var c={slug:a,id:n,country:`ID`,region:t,servings:4,minutes:173,title:d,text:l,steps:g};export{s as country,c as default,n as id,r as minutes,t as region,o as servings,a as slug,g as steps,l as text,d as title};